18	  "grok-4.20-multi-agent-console",
19	  "grok-4.20-multi-agent-low",
20	  "grok-4.20-multi-agent-medium",
21	  "grok-4.20-multi-agent-high",
22	  "grok-4.20-multi-agent-xhigh",
23	]);
