25	class CliError extends Error {
26	  constructor(message, exitCode = 1) {
27	    super(message);
28	    this.name = "CliError";
29	    this.exitCode = exitCode;
30	  }
31	}
32	
33	function printHelp() {
34	  console.log(`Usage:
35	  node scripts/grok-search.mjs --query "..." [options]
36	
37	Required:
38	  --query <text>          Search question or research task.
39	
40	Options:
41	  --effort <effort>       Reasoning effort: low, medium, high, or xhigh. Default: medium.
42	  --effort-model <mode>   Apply effort as reasoning field or model alias. Default: reasoning.
43	  --format <format>       Output format: text or json. Default: text.
44	  --base-url <url>        grok2api base URL. Env: GROK_SEARCH_BASE_URL.
45	  --api-key <key>         grok2api API key. Env: GROK_SEARCH_API_KEY.
46	  --model <model>         Model. Env: GROK_SEARCH_MODEL. Default: ${DEFAULT_MODEL}.
47	  Env default effort:     GROK_SEARCH_EFFORT.
48	  --timeout-ms <number>   Request timeout in milliseconds. Default: 120000.
49	  -h, --help              Show this help.
50	`);
51	}
52	
53	function parseArgs(argv) {
54	  const args = {};
55	
56	  for (let i = 0; i < argv.length; i += 1) {
57	    const token = argv[i];
58	
59	    if (token === "-h" || token === "--help") {
60	      args.help = true;
61	      continue;
62	    }
63	
64	    if (!token.startsWith("--")) {
65	      throw new CliError(`Unexpected positional argument: ${token}`);
66	    }
67	
68	    const eqIndex = token.indexOf("=");
69	    let key;
70	    let value;
71	
72	    if (eqIndex === -1) {
73	      key = token.slice(2);
74	      value = argv[i + 1];
75	      if (value === undefined || value.startsWith("--")) {
76	        throw new CliError(`Missing value for --${key}`);
77	      }
78	      i += 1;
79	    } else {
80	      key = token.slice(2, eqIndex);
81	      value = token.slice(eqIndex + 1);
82	    }
